  const log = (S, col) => { const k = ymd(Date.now()); const r = S.act[k] || (S.act[k] = { lessons: 0, tasks: 0, quizzes: 0, runs: 0, solved: 0 }); r[col]++; if (!S.joined) S.joined = k + " 00:00:00"; };
  const ok = d => ({ status: 200, data: d }), err = (s, m) => ({ status: s, data: { error: m } });
